def _quantidade(valor):
    """numero_de_equipamentos é texto livre: só dígitos viram quantidade (o
    resto vira 0, o mesmo critério do `_quantidade` da API de IDs)."""
    valor = (valor or "").strip()
    return int(valor) if valor.isdigit() else 0


def _backfill_itens(apps, schema_editor):
    """Cada requisição existente vira 1 item com os valores que ela já tinha
    (até aqui a requisição só aceitava um tipo de produto)."""
