    ItemRequisicao = apps.get_model('requisicao', 'ItemRequisicao')

    ja_migradas = set(ItemRequisicao.objects.values_list('requisicao_id', flat=True))
    campos = ('id', 'tipo_produto_id', 'numero_de_equipamentos', 'tipo_customizacao',
              'valor_unitario')
    itens = [
        ItemRequisicao(
            requisicao_id=rid,
            tipo_produto_id=produto_id,
            quantidade=_quantidade(numero),
            customizacao=customizacao or '',
            valor_unitario=valor or 0,
        )
        for rid, produto_id, numero, customizacao, valor
        in Requisicoes.objects.values_list(*campos).iterator()
        if rid not in ja_migradas  # idempotente
    ]
    ItemRequisicao.objects.bulk_create(itens, batch_size=500)


